class Renderer(RendererSpawn):

    async def warm_up(self, *, project: Path, ansi: bool, dark: bool) -> None:
        """Optional off-loop preparation after the application presents its UI."""

    @abstractmethod
    async def submit(self, task: RenderTask[ResultT]) -> ResultT:
        """Prepare one typed result, retaining admission until execution finishes."""

    @abstractmethod
    async def aclose(self) -> None:
        """Close this client's owned work and transport resources."""

class PersistentRenderClient(Renderer):
    """Construct synchronously; resolve code identity and connect only on demand.

    Initializing and retiring a client are owned operations, independent of any
    single widget waiter. A failed request is reported, never silently replayed;
    later requests may attach through a new client after the old one is drained.
    """

    def __init__(self, directory: Path, config: RenderServiceConfig=RenderServiceConfig()) -> None:
        self.directory, self.config = (directory, config)
        self._loop: asyncio.AbstractEventLoop | None = None
        self._initialization: asyncio.Task[PersistentRendererPool] | None = None
        self._retirement: asyncio.Task[None] | None = None
        self._shutdown: asyncio.Task[None] | None = None
        self._closed = False

    @property
    def resolved_pool(self) -> PersistentRendererPool | None:
        """The actual resolved backend, or None before successful initialization."""
        task = self._initialization
        if task is None or not task.done() or task.cancelled() or (task.exception() is not None):
            return None
        return task.result()

    def _bind_loop(self) -> None:
        loop = asyncio.get_running_loop()
        if self._loop is None:
            self._loop = loop
        elif loop is not self._loop:
            raise RuntimeError('PersistentRenderer must use its owning event loop')

    async def _initialize(self) -> PersistentRendererPool:
        endpoint = await asyncio.to_thread(RendererEndpoint.for_runtime, self.directory, self.config)
        return PersistentRendererPool(endpoint, self.config)

    async def _get_pool(self) -> PersistentRendererPool:
        self._bind_loop()
        retirement = self._retirement
        if retirement is not None:
            await asyncio.wait((retirement,))
            retirement.result()
            if self._retirement is retirement:
                self._retirement = None
        if self._closed:
            raise RuntimeError('Persistent renderer is closed')
        if self._initialization is None:
            self._initialization = asyncio.create_task(self._initialize(), name='renderer-initialize')
            self._initialization.add_done_callback(_observe)
        initialization = self._initialization
        await asyncio.wait((initialization,))
        if self._closed:
            raise RuntimeError('Persistent renderer is closed')
        try:
            return initialization.result()
        except Exception:
            if self._initialization is initialization:
                self._initialization = None
            raise

    def _retire(self, pool: PersistentRendererPool) -> None:
        if self.resolved_pool is pool:
            self._initialization = None
            self._retirement = asyncio.create_task(pool.aclose(), name='renderer-retire-failed-client')
            self._retirement.add_done_callback(_observe)

    async def submit(self, task: RenderTask[ResultT]) -> ResultT:
        pool = await self._get_pool()
        try:
            return await pool.submit(task)
        except RendererSessionFailed:
            self._retire(pool)
            raise

    async def warm_up(self, *, project: Path, ansi: bool, dark: bool) -> None:
        """Start matching workers and common parser/highlighter imports off-loop.

        These small, data-only tasks use normal admission and cancellation. No
        source files are opened, no user history is fetched and nothing is mounted.
        """
        tokens = await self.submit(MarkdownSyntaxRenderTask('```python\npass\n```\n\n```json\n{}\n```\n'))
        await asyncio.gather(self.submit(TokenRenderTask(tuple(tokens), ansi, dark)), self.submit(PatchRenderTask('--- warmup.py\n+++ warmup.py\n@@ -1 +1 @@\n-pass\n+value = 1\n', ansi, dark)))

    async def aclose(self) -> None:
        self._bind_loop()
        self._closed = True
        if self._shutdown is None:
            self._shutdown = asyncio.create_task(self._close(), name='renderer-runtime-close')
            self._shutdown.add_done_callback(_observe)
        await asyncio.wait((self._shutdown,))
        self._shutdown.result()

    async def _close(self) -> None:
        try:
            initialization = self._initialization
            if initialization is not None:
                await asyncio.wait((initialization,))
                if not initialization.cancelled() and initialization.exception() is None:
                    await initialization.result().aclose()
        finally:
            retirement = self._retirement
            if retirement is not None:
                await asyncio.wait((retirement,))
                retirement.result()

class RenderTask(RenderExecution[ResultT], DeclaredFamily, affix='RenderTask'):
    """A nominal operation with an exact input and result contract."""

    def reusable_inputs(self) -> object | None:
        """None means external state prevents sharing or retaining this capture."""
        return None

class ReusableRenderTask(RenderTask[ResultT]):

    def reusable_inputs(self) -> object:
        return self

class SidebarObservation:

    def __init__(self, sidebar, *, enabled: bool):
        self.sidebar = sidebar
        self.enabled = enabled
        self.service = None
        self.task = None
        self.lock = asyncio.Lock()
        self.identity = None
        self.read_marker_notice = None

    @property
    def pending(self) -> bool:
        task = self.task
        return self.lock.locked() or (task is not None and (not task.done()))

    async def close(self) -> None:
        task = self.task
        if task is not None:
            task.cancel()
            await asyncio.gather(task, return_exceptions=True)

    def mount(self) -> None:
        from toad.comms_root import current_root
        from toad.screens.comms import CommsScreen
        app = self.sidebar.app
        try:
            root = current_root().resolve()
        except (OSError, ValueError, RuntimeError):
            self.sidebar.display = False
            return
        screen = self.sidebar.screen
        if isinstance(screen, CommsScreen) and (not screen.belongs_to_wire(root)):
            self.sidebar.display = False
            return
        service = app.coordination_access.service
        self.service = service if root == service.root else wire(root)
        app.session_update_signal.subscribe(self.sidebar, self.session_updated)
        app.session_selected_signal.subscribe(self.sidebar, self.sidebar.navigation.mode_changed)
        app.thread_actions_changed.subscribe(self.sidebar, self.actions_changed)
        app.settings_changed_signal.subscribe(self.sidebar, self.settings_changed)
        app.coordination_observed.subscribe(self.sidebar, self.coordination_updated)
        self.sidebar.navigation.prepare()
        from toad.screens.workspace import WorkspaceScreen
        if isinstance(screen, WorkspaceScreen):
            screen.frame_presentation.defer(self.sidebar, self.sidebar.navigation.start)
        self.after_frame()

    def set_enabled(self, enabled: bool) -> None:
        self.enabled = enabled
        self.sidebar.projection.sync_spinner()

    def read_identity(self, revision: WireRevision) -> SidebarReadIdentity:
        return SidebarReadIdentity(revision, self.sidebar.session_thread, self.visible_filters)

    def project(self, state):
        return SidebarSnapshot.capture(self.sidebar.app, self.service, state)

    def invalidate(self) -> None:
        self.identity = None

    def after_frame(self) -> None:
        from toad.screens.workspace import WorkspaceScreen
        screen = self.sidebar.screen
        if isinstance(screen, WorkspaceScreen):
            screen.frame_presentation.defer(self.sidebar, self.start_read)
        else:
            self.sidebar.call_after_refresh(self.start_read)

    async def bind(self, service: Comms) -> None:
        """Rebind shared navigation only through the app's validated route owner."""
        if self.service is service:
            return
        self.sidebar.display = False
        async with self.sidebar.projection.lock:
            self.service = service
            self.sidebar.projection.snapshot = None
            self.identity = None
            self.sidebar.navigation.reset()
            self.sidebar.projection.paint = None
            for group in self.sidebar.query(ChannelGroup):
                group._snapshot = None
            self.sidebar.projection.sync_spinner()

    async def session_updated(self, update: tuple[str, SessionDetails | None]) -> None:
        if not self.accepts_observation():
            return
        if self.sidebar.projection.has_snapshot():
            await self.sidebar.projection.publish(self.project(self.sidebar.projection.snapshot.wire))
        self.sidebar.navigation.mode_changed(self.sidebar.app.selected_mode)
        self.refresh()

    async def sync(self) -> None:
        """Reconcile tracked rows before a resumed screen accepts input."""
        async with self.lock:
            revision = self.service.views.revision()
            if self.sidebar.projection.has_snapshot() and self.read_identity(revision) == self.identity:
                await self.sidebar.projection.publish(self.project(self.sidebar.projection.snapshot.wire))
            else:
                await self.read(revision)

    async def actions_changed(self, _update: None) -> None:
        if not self.accepts_observation():
            self.identity = None
            return
        if self.sidebar.projection.has_snapshot() and self.sidebar.is_attached:
            await self.sidebar.projection.publish(self.sidebar.projection.snapshot)
        self.identity = None
        self.refresh()

    async def present_cached(self) -> None:
        """Paint the last observed projection; refresh disk state after activation."""
        if not self.accepts_observation():
            return
        state = self.sidebar.app._sidebar_snapshot
        if state is not None and (state.show_stopped, state.show_archived) == self.visible_filters:
            await self.sidebar.projection.publish(self.project(state))
        self.after_frame()

    @property
    def visible_filters(self) -> tuple[bool, bool]:
        settings = self.sidebar.app.settings
        return (settings.sidebar.show_stopped, settings.sidebar.show_archived)

    def settings_changed(self, update: PreferenceChange) -> None:
        if update.field in {SidebarSettings.show_stopped, SidebarSettings.show_archived}:
            self.identity = None
            self.refresh()

    def registry_names(self) -> list[str]:
        """Registered thread names on the wire (for view toggles)."""
        try:
            local_threads = self.sidebar.app.local_coordination_threads()
            return [name for name in wire(current_root()).registry.active_threads() if name not in local_threads]
        except Exception:
            return []

    def route_changed(self) -> bool:
        return self.sidebar.app.coordination_access.route_changed()

    async def coordination_updated(self, _event=None) -> None:
        service = self.sidebar.app.coordination_access.observed_service
        if service is not None:
            await self.bind(service)
        self.refresh()

    def accepts_observation(self) -> bool:
        from toad.widgets.side_bar import SideBar
        return self.enabled and self.sidebar.accepts_publication() and (not self.sidebar.query_ancestor(SideBar).collapsed)

    def refresh(self) -> None:
        if not self.accepts_observation():
            return
        if self.service is None:
            self.sidebar.display = False
            return
        self.after_frame()

    def start_read(self) -> None:
        if not self.accepts_observation():
            return
        try:
            if self.sidebar.screen is not self.sidebar.app.screen:
                return
            if self.route_changed():
                self.sidebar.display = False
            if self.pending:
                return
            revision = self.service.views.revision()
            if self.sidebar.display and self.read_identity(revision) == self.identity:
                return
            self.task = asyncio.create_task(self.refresh_checked(revision))
        except Exception:
            self.sidebar.display = False

    async def refresh_checked(self, revision: WireRevision) -> None:
        service = self.service
        try:
            from toad.comms_root import root_is_current
            if not await asyncio.to_thread(root_is_current, service.root):
                if self.service is service:
                    self.sidebar.display = False
                return
            if self.service is not service or not self.sidebar.accepts_publication():
                return
            await self.poll(revision)
            if self.service is service and self.identity == self.read_identity(revision):
                if not await asyncio.to_thread(root_is_current, service.root):
                    return
                if self.service is not service:
                    return
                self.sidebar.display = True
                if not self.sidebar.navigation.ready.is_set():
                    self.sidebar.call_after_refresh(self.sidebar.navigation.finish, self.sidebar.navigation.revision)
        except Exception:
            return

    async def poll(self, revision: WireRevision) -> None:
        service = self.service
        async with self.lock:
            if self.service is not service:
                return
            if self.sidebar.projection.has_snapshot() and self.read_identity(revision) == self.identity:
                await self.sidebar.app.mark_visible_thread_read()
                revision = service.views.revision()
                if self.service is not service:
                    return
                if self.identity == self.read_identity(revision):
                    self.identity = self.read_identity(revision)
                    await self.sidebar.projection.publish(self.project(self.sidebar.projection.snapshot.wire))
                    return
            await self.read(revision)

    async def read(self, revision: WireRevision) -> None:
        service = self.service
        try:
            actor = self.sidebar.session_thread
            filters = self.visible_filters
            await self.sidebar.app.mark_visible_thread_read()
            state = await asyncio.to_thread(service.views.viewer_snapshot, str(self.sidebar.app.project_dir), show_stopped=filters[0], show_archived=filters[1])
            if self.service is not service or not self.sidebar.accepts_publication():
                return
            if SidebarReadIdentity(revision, actor, filters) != self.read_identity(revision):
                return
            from toad.comms_root import root_is_current
            if not await asyncio.to_thread(root_is_current, service.root):
                if self.service is service:
                    self.sidebar.display = False
                return
            if self.service is not service:
                return
            snapshot = self.project(state)
            if state.read_marker_notice != self.read_marker_notice:
                self.read_marker_notice = state.read_marker_notice
                if state.read_marker_notice:
                    self.sidebar.notify(state.read_marker_notice, title='Read positions', severity='warning')
            app = self.sidebar.app
            previous_tabs = app.open_tabs
            app._sidebar_snapshot = state
            self.identity = SidebarReadIdentity(revision, actor, filters)
            await self.sidebar.projection.publish(snapshot)
            if app.open_tabs != previous_tabs:
                app.open_tabs_changed.publish(None)
        except (OSError, ValueError):
            return

@dataclass(frozen=True)
class PreparedThreadRow:
    source: ThreadRowPresentation
    frames: tuple[Content, ...]
    tooltip: Content
    busy: bool
    signature: tuple[str, str, bool]

    def content(self, phase: int) -> Content:
        return self.frames[phase % len(self.frames)]

@dataclass(frozen=True)
class ThreadRowsWork(SerializedWork[tuple[PreparedThreadRow, ...]], ContentAddressedWork[tuple[PreparedThreadRow, ...]], ThreadWork[tuple[PreparedThreadRow, ...]]):
    rows: tuple[ThreadRowInput, ...]

    @property
    def inputs(self) -> object:
        return tuple((row.presentation() for row in self.rows))

    def prepare(self) -> tuple[PreparedThreadRow, ...]:
        return tuple((prepare_thread_row(row) for row in self.rows))

@dataclass(frozen=True)
class PreparedTab:
    source: OpenTab
    frames: tuple[Content, ...]

    def content(self, phase: int) -> Content:
        return self.frames[phase % len(self.frames)]

@dataclass(frozen=True)
class TabRosterWork(SerializedWork[tuple[PreparedTab, ...]], ContentAddressedWork[tuple[PreparedTab, ...]], ThreadWork[tuple[PreparedTab, ...]]):
    tabs: tuple[OpenTab, ...]

    @property
    def inputs(self) -> object:
        return self.tabs

    def prepare(self) -> tuple[PreparedTab, ...]:
        return tuple((prepare_tab(tab) for tab in self.tabs))

class SidebarProjection:

    def __init__(self, sidebar):
        self.sidebar = sidebar
        self.snapshot = None
        self.paint = None
        self.lock = asyncio.Lock()
        self.phase = 0
        self.timer = None
        self.horizontal_width = 0

    @property
    def channels(self):
        from toad.widgets.comms_sidebar import ChannelGroup
        return {group.row.target_name: group.row for group in self.sidebar.children if isinstance(group, ChannelGroup)}

    @property
    def rows(self):
        from toad.widgets.comms_sidebar import ChannelGroup
        return [row for group in self.sidebar.children if isinstance(group, ChannelGroup) for row in (group.row, *group.member_container.children) if row.is_navigation_row()]

    def painted_busy_rows(self):
        """Animate only rows admitted by the current native paint scene.

        Navigation owns the whole roster. Its attachment walk is not an
        animation census, and offscreen rows have no spinner pixels to paint.
        Read the compositor's existing visible custody without retaining a
        competing row list or busy-state index.
        """
        from toad.widgets.comms_sidebar import CommsRow
        for row in self.sidebar.screen._compositor.visible_widgets:
            if isinstance(row, CommsRow) and row.has_class('-busy'):
                if row.is_navigation_row() and row.sidebar_owner() is self.sidebar:
                    yield row

    @property
    def thread_rows(self):
        from toad.widgets.comms_sidebar import ChannelGroup
        return [row for group in self.sidebar.children if isinstance(group, ChannelGroup) for row in group.member_container.children]

    @property
    def session_rows(self):
        return [row for row in self.thread_rows if row.has_open_view()]

    def mount(self) -> None:
        self.timer = self.sidebar.set_interval(1 / self.sidebar.app.settings.sidebar.spinner_frames_per_second, self.animate, pause=True)

    def update_animation_cadence(self) -> None:
        if self.timer is not None:
            self.timer.stop()
            self.mount()
            self.sync_spinner()

    def pause_spinner(self) -> None:
        if self.timer is not None:
            self.timer.pause()

    def has_snapshot(self) -> bool:
        return self.snapshot is not None

    def sync_spinner(self, snapshot: SidebarSnapshot | None=None) -> None:
        timer = self.timer
        if timer is None:
            return
        active = self.sidebar.shows_rows() and self.sidebar.observation.enabled
        if active and self.has_snapshot() and any((row.has_class('-busy') for row in self.rows)):
            timer.resume()
        else:
            timer.pause()

    def animate(self) -> None:
        if not self.sidebar.shows_rows() or self.snapshot is None:
            self.sync_spinner()
            return
        self.phase = (self.phase + 1) % len(FRAMES)
        for row in self.painted_busy_rows():
            row.advance_spinner(self.phase)

    async def publish(self, snapshot: SidebarSnapshot) -> None:
        service = self.sidebar.observation.service
        async with self.lock:
            if self.sidebar.observation.service is not service or not self.sidebar.accepts_publication():
                return
            paint = SidebarPaint(snapshot, tuple(self.sidebar.navigation.state.expanded.items()), tuple(self.sidebar.app.thread_actions.pending.items()))
            if paint != self.paint:
                await self.rebuild(snapshot)
                if not self.sidebar.accepts_publication():
                    return
                self.paint = paint
            else:
                self.sidebar.navigation.apply()
                self.sidebar.navigation.mode_changed(self.sidebar.app.selected_mode)
                self.sync_spinner(snapshot)
            if not self.sidebar.navigation.ready.is_set() and self.sidebar.is_attached and self.sidebar.screen.is_current:
                self.sidebar.call_after_refresh(self.sidebar.navigation.finish, self.sidebar.navigation.revision)

    async def rebuild(self, snapshot: SidebarSnapshot) -> None:
        if not self.sidebar.accepts_publication():
            return
        self.snapshot = snapshot
        channels = self.channels
        from toad.widgets.comms_sidebar import CommsRow, ChannelGroup, NewSessionButton
        from toad.navigation_target import channel_target
        from toad.widgets.session_sort import ChannelListSort
        from toad.widgets.side_bar import SideBarCollapsible
        control = self.sidebar.query_ancestor(SideBarCollapsible).header_control
        assert isinstance(control, ChannelListSort)
        control.update_order(snapshot.wire.channel_order)
        desired_keys = [view.channel.name for view in snapshot.wire.channels]
        if not self.sidebar.query(NewSessionButton):
            await self.sidebar.mount(NewSessionButton())
            if not self.sidebar.accepts_publication():
                return
        for key in set(channels) - set(desired_keys):
            row = channels.pop(key)
            await row.query_ancestor(ChannelGroup).remove()
            if not self.sidebar.accepts_publication():
                return
        new_groups: list[ChannelGroup] = []
        for key in desired_keys:
            if key not in channels:
                row = channels[key] = CommsRow(channel_target(key), key)
                new_groups.append(ChannelGroup(row, expanded=self.sidebar.navigation.state.expanded.get(key, row.target.expanded_by_default)))
        if new_groups:
            await self.sidebar.mount(*new_groups)
            if not self.sidebar.accepts_publication():
                return
        for view in snapshot.wire.channels:
            channel_row = channels[view.channel.name]
            unread = snapshot.wire.channel_unread.get(view.channel.name, 0)
            channel_row.set_label(f"{('* ' if view.channel.pinned else '')}{view.channel.name}")
            group = channel_row.query_ancestor(ChannelGroup)
            group.update_unread(unread)
            group.update_activity(view, snapshot.all_people)
            channel_row.set_class(bool(unread), '-unread')
            await group.present(view, snapshot)
            if not self.sidebar.accepts_publication():
                return
        ordered = [self.sidebar.query_one(NewSessionButton), *(channels[key].query_ancestor(ChannelGroup) for key in desired_keys)]
        if list(self.sidebar.children) != ordered:
            positions = {widget: index for index, widget in enumerate(ordered)}
            self.sidebar.sort_children(key=positions.__getitem__)
        self.sidebar.navigation.apply(force=True)
        self.sidebar.navigation.mode_changed(self.sidebar.app.selected_mode, force=True)
        self.sync_spinner(snapshot)
        widest = max((Content(view.channel.name).cell_length + 12 for view in snapshot.wire.channels), default=0)
        widest = max(widest, max((Content(person.presentation.label).cell_length + 8 for person in snapshot.all_people.values()), default=0))
        widest = max(widest, max((Content(person.presentation.summary).cell_length + 8 for person in snapshot.all_people.values()), default=0))
        widest = min(widest, 512)
        panel = self.sidebar.query_ancestor(SideBarCollapsible)
        if widest != self.horizontal_width:
            self.horizontal_width = widest
            panel.styles.min_width = widest

class SessionsTabs(Widget):
    ALLOW_SELECT = False
    app: getters.app[ToadApp] = getters.app(ToadApp)
    title_container = getters.query_one('#title-container', Widget)
    current_session = reactive('', init=False)
    _last_tabs: tuple[OpenTab, ...] | None = None

    def __init__(self) -> None:
        super().__init__()
        self._spinner_phase = 0
        self._spinner_timer = None
        self._sync_lock = asyncio.Lock()
        self._tab_projection: dict[str, PreparedTab] = {}

    def _get_scrollable_region(self, region: Region) -> Region:
        window = super()._get_scrollable_region(region)
        return window.grow((0, 0, self.scrollbar_size_horizontal, 0))

    def _arrange_scrollbars(self, region: Region) -> Iterable[tuple[Widget, Region]]:
        for scrollbar, scrollbar_region in super()._arrange_scrollbars(region):
            if scrollbar is self.horizontal_scrollbar:
                scrollbar_region = scrollbar_region.translate((0, region.y - scrollbar_region.y))
            yield (scrollbar, scrollbar_region)

    def _sync_spinner(self, tabs: tuple[OpenTab, ...]) -> None:
        timer = self._spinner_timer
        if timer is None:
            return
        if self.screen.is_active and any((tab.title.startswith(('⌛ ', '● ')) for tab in tabs)):
            timer.resume()
        else:
            timer.pause()

    def _animate_busy(self) -> None:
        tabs = self._last_tabs or ()
        if not self.screen.is_active or not any((tab.title.startswith(('⌛ ', '● ')) for tab in tabs)):
            self._sync_spinner(())
            return
        self._spinner_phase = (self._spinner_phase + 1) % len(FRAMES)
        for tab in tabs:
            if tab.title.startswith(('⌛ ', '● ')) and (label := self.query_one_optional(f'#{tab.mode_name}', SessionLabel)):
                label.update(self.render_session_label(tab), layout=False)

    def on_mount(self) -> None:
        self._spinner_timer = self.set_interval(0.18, self._animate_busy, pause=True)
        self.current_session = self.app.selected_mode
        self.app.session_selected_signal.subscribe(self, self.handle_mode_change)
        self.app.session_update_signal.subscribe(self, self.handle_session_update_signal)
        self.app.open_tabs_changed.subscribe(self, self._tabs_changed)
        self.call_later(self._sync_tabs)
        self.update_underline(self.current_session, animate=False)
        self.call_after_refresh(self.update_underline, self.current_session)
        self._sync_spinner(self.app.open_tabs)

    def handle_mode_change(self, mode: str) -> None:
        if self.screen.is_active:
            self.call_later(self._sync_tabs)

    def watch_current_session(self, old_session: str, new_session: str) -> None:
        self.query('.-current').remove_class('-current')
        self.query(f'#{new_session}').add_class('-current')
        if self.app._atomic_mode_switch:
            self.call_after_refresh(self.update_underline, new_session, False)
            return
        if old_session:
            self.update_underline(old_session, animate=False)
        self.update_underline(new_session, animate=False)

    def update_underline(self, session: str | None=None, animate: bool=True):
        if not self.is_mounted or not self.is_attached:
            return
        if session is None:
            session = self.current_session
        if not session:
            return
        if (current_label := self.query_one_optional(f'#{session}', SessionLabel)):
            tab_region = current_label.virtual_region.shrink((0, 1, 0, 1))
            if not tab_region:
                return
            start, end = tab_region.column_span
            underline = self.query_one(Underline)
            if animate:
                underline.animate('highlight_start', start, duration=0.3)
                underline.animate('highlight_end', end, duration=0.3, on_complete=partial(self.scroll_to_center, current_label))
            else:
                underline.highlight_start = start
                underline.highlight_end = end
                self.scroll_to_center(current_label, animate=False)

    def render_session_label(self, session: OpenTab) -> Content:
        prepared = self._tab_projection.get(session.mode_name)
        if prepared is not None and prepared.source == session:
            return prepared.content(self._spinner_phase)
        title = animated_label(session.title, busy=session.title.startswith(('⌛ ', '● ')), phase=self._spinner_phase)
        if session.unread.label:
            return Content.assemble(title, (f' {session.unread.label}', 'bold $accent'))
        return Content(title)

    def compose(self) -> ComposeResult:
        tabs = self.app.open_tabs
        self._last_tabs = tabs
        with containers.HorizontalGroup(id='title-container'):
            for session in tabs:
                yield SessionLabel(self.render_session_label(session), id=session.mode_name, classes='-current' if session.mode_name == self.app.selected_mode else '')
                yield SessionTabClose(session.mode_name)
        yield Underline()

    async def handle_session_update_signal(self, update: tuple[str, SessionDetails | None]) -> None:
        if self.screen.is_active:
            await self._sync_tabs()

    async def _tabs_changed(self, _update: None) -> None:
        if self.screen.is_active:
            await self._sync_tabs()

    async def _sync_tabs(self) -> None:
        async with self._sync_lock:
            await self._reconcile_tabs()

    async def _reconcile_tabs(self) -> None:
        if not self.is_attached or not self.screen.is_active:
            return
        while True:
            tabs = self.app.open_tabs
            if tabs == self._last_tabs:
                self.current_session = self.app.selected_mode
                self._sync_spinner(tabs)
                return
            prepared = await self.app.preparation.submit(TabRosterWork(tabs))
            if not self.is_attached or not self.screen.is_active:
                return
            if tabs == self.app.open_tabs:
                break
        self._tab_projection = {tab.source.mode_name: tab for tab in prepared}
        previous_tabs = {tab.mode_name: tab for tab in self._last_tabs or ()}
        geometry_changed = self._last_tabs is None
        mode_changed = self.current_session != self.app.selected_mode
        labels = {label.id: label for label in self.query(SessionLabel)}
        desired = {tab.mode_name for tab in tabs}
        obsolete = set(labels) - desired
        if obsolete:
            retired_ids = obsolete | {f'close-{identity}' for identity in obsolete}
            await self.title_container.remove_children((child for child in self.title_container.children if child.id in retired_ids))
            geometry_changed = True
        new_widgets: list[Widget] = []
        for tab in tabs:
            content = self.render_session_label(tab)
            if (label := labels.get(tab.mode_name)):
                if label.render().plain != content.plain:
                    previous = previous_tabs.get(tab.mode_name)
                    same_width_count = previous is not None and previous.title == tab.title and (previous.unread.highlighted == tab.unread.highlighted) and (len(previous.unread.label) == len(tab.unread.label))
                    label.update(content, layout=not same_width_count)
                    geometry_changed |= not same_width_count
            else:
                new_widgets.extend((SessionLabel(content, id=tab.mode_name), SessionTabClose(tab.mode_name)))
                geometry_changed = True
        if new_widgets:
            await self.title_container.mount(*new_widgets)
        order = {identity: index for index, identity in enumerate((identity for tab in tabs for identity in (tab.mode_name, f'close-{tab.mode_name}')))}
        if [widget.id for widget in self.title_container.children] != list(order):
            self.title_container.sort_children(key=lambda widget: order[widget.id])
            geometry_changed = True
        self.current_session = self.app.selected_mode
        self._last_tabs = tabs
        self._sync_spinner(tabs)
        if geometry_changed or mode_changed:
            self.call_after_refresh(self.update_underline, self.current_session, False)

class RelationshipRows(SidebarGroup):
    DEFAULT_CSS = '\n    RelationshipRows > .group-header > SidebarDisclosure { width: 1; }\n    '
    EMPTY = {'inbound': 'No recent inbound', 'outbound': 'No recent outbound', 'parent': 'Not forked', 'children': 'No children', 'collaborating': 'No active collaborations'}

    def __init__(self, model: RelationshipGroup, expanded: bool):
        self.model = model
        self.rows: dict[tuple[str, str], RelationshipRow] = {}
        super().__init__(Static(model.title), expanded=expanded, scrollable=False, id=f'relationships-{model.key}')

    async def update_group(self, model: RelationshipGroup) -> None:
        async with self.member_lock:
            self.model = model
            await self._reconcile_members()

    async def _reconcile_members(self) -> None:
        if not self.is_mounted:
            return
        tree = self.query_ancestor(ThreadCommsSidebar)
        state = tree.view_state
        container = self.member_container
        entries = {(entry.kind, entry.target): entry for entry in self.model.entries}
        model, owner = (self.model, tree.owner)
        row_keys = tuple((key for key, entry in entries.items() if entry.available and entry.person is not None))
        inputs = {key: ThreadRowInput(entries[key].person, unread=tree.unread(person_target(entries[key].person)), action_status=tree.app.thread_actions.pending.get(entries[key].target)) for key in row_keys} if self.expanded else {}
        prepared_rows = await self.prepare_thread_rows(inputs, self.rows)
        if not self.is_attached or self.model is not model or tree.owner != owner:
            return
        if not self.expanded:
            if container.display:
                state.scroll[self.model.key] = container.scroll_y
            container.display = False
            return
        was_hidden = not container.display
        container.display = True
        empty = container.query_one_optional('.relationship-empty')
        if entries and empty is not None:
            await empty.remove()
        if not entries and empty is None:
            await container.mount(Static(self.EMPTY[self.model.key], classes='relationship-empty'))
        old_scroll = container.scroll_y
        anchor = next((row for row in container.children if isinstance(row, RelationshipRow) and row.region.bottom > container.content_region.y), None) if old_scroll > 0 else None
        previous_order = tuple(container.children)

        def create(key):
            entry = entries[key]
            target = person_target(entry.person) if entry.person else linked_target(entry.target)
            return RelationshipRow(target, entry.target)

        def update(key, row):
            entry = entries[key]
            row.entry = entry
            row.available = entry.available
            row.target = person_target(entry.person) if entry.person else linked_target(entry.target)
            if not entry.available:
                row.remove_class('-busy', '-unread', '-current')
                row.add_class('-wire-thread')
                row._thread_signature = None
                _update_content(row, Content(f'? {entry.target}\n  Unavailable · Ctrl+C copies name'))
            elif entry.person is not None:
                row.apply_thread_preparation(prepared_rows[key])
            else:
                row.set_label(entry.target)
                row.tooltip = entry.target
            if entry.detail:
                row.tooltip = Content(f'{entry.target}\n{entry.detail}')
            row.set_class(state.selected == (self.model.key, entry.target), '-selected')
        ordered = await self.reconcile_rows(entries, self.rows, create, update)
        if ordered != previous_order:
            if old_scroll > 0 and anchor in ordered:
                new_y = sum((2 if row.has_class('-wire-thread') else 1 for row in ordered[:ordered.index(anchor)]))
                container.scroll_to(y=new_y, animate=False, immediate=True)
        if was_hidden:
            container.scroll_to(y=state.scroll.get(self.model.key, 0), animate=False)

class ThreadWork(PreparationWork[ResultT]):
    lane = WorkLane.MODEL

    @abstractmethod
    def prepare(self) -> ResultT:
        """Prepare captured data on a worker thread."""

    async def execute(self, runtime: PreparationRuntime) -> ResultT:
        return await runtime.run_thread(self.prepare)

class RendererWork(PreparationWork[ResultT]):
    lane = WorkLane.RENDER

    @property
    @abstractmethod
    def render_task(self) -> RenderTask[ResultT]:
        """A task admitted by the existing local/persistent renderer."""

    async def execute(self, runtime: PreparationRuntime) -> ResultT:
        return await runtime.renderer.submit(self.render_task)

class Renderer:

    def __init__(self):
        self.threads = []

    async def submit(self, task):

        def execute():
            self.threads.append(threading.get_ident())
            return task.execute()
        return await asyncio.to_thread(execute)

    async def aclose(self):
        pass

class Renderer(RendererSpawn):

    async def warm_up(self, *, project: Path, ansi: bool, dark: bool) -> None:
        """Optional off-loop preparation after the application presents its UI."""

    @abstractmethod
    async def submit(self, task: RenderTask[ResultT]) -> ResultT:
        """Prepare one typed result, retaining admission until execution finishes."""

    @abstractmethod
    async def aclose(self) -> None:
        """Close this client's owned work and transport resources."""

class PersistentRenderClient(Renderer):
    """Construct synchronously; resolve code identity and connect only on demand.

    Initializing and retiring a client are owned operations, independent of any
    single widget waiter. A failed request is reported, never silently replayed;
    later requests may attach through a new client after the old one is drained.
    """

    def __init__(self, directory: Path, config: RenderServiceConfig=RenderServiceConfig()) -> None:
        self.directory, self.config = (directory, config)
        self._loop: asyncio.AbstractEventLoop | None = None
        self._initialization: asyncio.Task[PersistentRendererPool] | None = None
        self._retirement: asyncio.Task[None] | None = None
        self._shutdown: asyncio.Task[None] | None = None
        self._closed = False

    @property
    def resolved_pool(self) -> PersistentRendererPool | None:
        """The actual resolved backend, or None before successful initialization."""
        task = self._initialization
        if task is None or not task.done() or task.cancelled() or (task.exception() is not None):
            return None
        return task.result()

    def _bind_loop(self) -> None:
        loop = asyncio.get_running_loop()
        if self._loop is None:
            self._loop = loop
        elif loop is not self._loop:
            raise RuntimeError('PersistentRenderer must use its owning event loop')

    async def _initialize(self) -> PersistentRendererPool:
        endpoint = await asyncio.to_thread(RendererEndpoint.for_runtime, self.directory, self.config)
        return PersistentRendererPool(endpoint, self.config)

    async def _get_pool(self) -> PersistentRendererPool:
        self._bind_loop()
        retirement = self._retirement
        if retirement is not None:
            await asyncio.wait((retirement,))
            retirement.result()
            if self._retirement is retirement:
                self._retirement = None
        if self._closed:
            raise RuntimeError('Persistent renderer is closed')
        if self._initialization is None:
            self._initialization = asyncio.create_task(self._initialize(), name='renderer-initialize')
            self._initialization.add_done_callback(_observe)
        initialization = self._initialization
        await asyncio.wait((initialization,))
        if self._closed:
            raise RuntimeError('Persistent renderer is closed')
        try:
            return initialization.result()
        except Exception:
            if self._initialization is initialization:
                self._initialization = None
            raise

    def _retire(self, pool: PersistentRendererPool) -> None:
        if self.resolved_pool is pool:
            self._initialization = None
            self._retirement = asyncio.create_task(pool.aclose(), name='renderer-retire-failed-client')
            self._retirement.add_done_callback(_observe)

    async def submit(self, task: RenderTask[ResultT]) -> ResultT:
        pool = await self._get_pool()
        try:
            return await pool.submit(task)
        except RendererSessionFailed:
            self._retire(pool)
            raise

    async def warm_up(self, *, project: Path, ansi: bool, dark: bool) -> None:
        """Start matching workers and common parser/highlighter imports off-loop.

        These small, data-only tasks use normal admission and cancellation. No
        source files are opened, no user history is fetched and nothing is mounted.
        """
        tokens = await self.submit(MarkdownSyntaxRenderTask('```python\npass\n```\n\n```json\n{}\n```\n'))
        await asyncio.gather(self.submit(TokenRenderTask(tuple(tokens), ansi, dark)), self.submit(PatchRenderTask('--- warmup.py\n+++ warmup.py\n@@ -1 +1 @@\n-pass\n+value = 1\n', ansi, dark)))

    async def aclose(self) -> None:
        self._bind_loop()
        self._closed = True
        if self._shutdown is None:
            self._shutdown = asyncio.create_task(self._close(), name='renderer-runtime-close')
            self._shutdown.add_done_callback(_observe)
        await asyncio.wait((self._shutdown,))
        self._shutdown.result()

    async def _close(self) -> None:
        try:
            initialization = self._initialization
            if initialization is not None:
                await asyncio.wait((initialization,))
                if not initialization.cancelled() and initialization.exception() is None:
                    await initialization.result().aclose()
        finally:
            retirement = self._retirement
            if retirement is not None:
                await asyncio.wait((retirement,))
                retirement.result()

class RenderTask(RenderExecution[ResultT], DeclaredFamily, affix='RenderTask'):
    """A nominal operation with an exact input and result contract."""

    def reusable_inputs(self) -> object | None:
        """None means external state prevents sharing or retaining this capture."""
        return None

class ReusableRenderTask(RenderTask[ResultT]):

    def reusable_inputs(self) -> object:
        return self

@dataclass(frozen=True)
class ThreadRowsRenderTask(ReusableRenderTask[tuple[PreparedThreadRow, ...]]):
    """Render captured display inputs without transporting backend authorities."""
    rows: tuple[ThreadRowPresentation, ...]

    def execute(self) -> tuple[PreparedThreadRow, ...]:
        return tuple((prepare_thread_presentation(row) for row in self.rows))

    def accept_result(self, result: object) -> tuple[PreparedThreadRow, ...]:
        if not isinstance(result, tuple) or not all((isinstance(row, PreparedThreadRow) for row in result)):
            raise TypeError('Thread row renderer returned an invalid result')
        return result

@dataclass(frozen=True)
class TabRosterRenderTask(ReusableRenderTask[tuple[PreparedTab, ...]]):
    """The same renderer prepares tab content under its existing admission bound."""
    tabs: tuple[OpenTab, ...]

    def execute(self) -> tuple[PreparedTab, ...]:
        return tuple((prepare_tab(tab) for tab in self.tabs))

    def accept_result(self, result: object) -> tuple[PreparedTab, ...]:
        if not isinstance(result, tuple) or not all((isinstance(tab, PreparedTab) for tab in result)):
            raise TypeError('Tab renderer returned an invalid result')
        return result

class SidebarObservation:

    def __init__(self, sidebar, *, enabled: bool):
        self.sidebar = sidebar
        self.enabled = enabled
        self.service = None
        self.task = None
        self.lock = asyncio.Lock()
        self.identity = None
        self.read_marker_notice = None

    @property
    def pending(self) -> bool:
        task = self.task
        return self.lock.locked() or (task is not None and (not task.done()))

    async def close(self) -> None:
        task = self.task
        if task is not None:
            task.cancel()
            await asyncio.gather(task, return_exceptions=True)

    def mount(self) -> None:
        from toad.comms_root import current_root
        from toad.screens.comms import CommsScreen
        app = self.sidebar.app
        try:
            root = current_root().resolve()
        except (OSError, ValueError, RuntimeError):
            self.sidebar.display = False
            return
        screen = self.sidebar.screen
        if isinstance(screen, CommsScreen) and (not screen.belongs_to_wire(root)):
            self.sidebar.display = False
            return
        service = app.coordination_access.service
        self.service = service if root == service.root else wire(root)
        app.session_update_signal.subscribe(self.sidebar, self.session_updated)
        app.session_selected_signal.subscribe(self.sidebar, self.sidebar.navigation.mode_changed)
        app.thread_actions_changed.subscribe(self.sidebar, self.actions_changed)
        app.settings_changed_signal.subscribe(self.sidebar, self.settings_changed)
        app.coordination_observed.subscribe(self.sidebar, self.coordination_updated)
        self.sidebar.navigation.prepare()
        from toad.screens.workspace import WorkspaceScreen
        if isinstance(screen, WorkspaceScreen):
            screen.frame_presentation.defer(self.sidebar, self.sidebar.navigation.start)
        self.after_frame()

    def set_enabled(self, enabled: bool) -> None:
        self.enabled = enabled
        self.sidebar.projection.sync_spinner()

    def read_identity(self, revision: WireRevision) -> SidebarReadIdentity:
        return SidebarReadIdentity(revision, self.sidebar.session_thread, self.visible_filters)

    def project(self, state):
        return SidebarSnapshot.capture(self.sidebar.app, self.service, state)

    def invalidate(self) -> None:
        self.identity = None

    def after_frame(self) -> None:
        from toad.screens.workspace import WorkspaceScreen
        screen = self.sidebar.screen
        if isinstance(screen, WorkspaceScreen):
            screen.frame_presentation.defer(self.sidebar, self.start_read)
        else:
            self.sidebar.call_after_refresh(self.start_read)

    async def bind(self, service: Comms) -> None:
        """Rebind shared navigation only through the app's validated route owner."""
        if self.service is service:
            return
        self.sidebar.display = False
        async with self.sidebar.projection.lock:
            self.service = service
            self.sidebar.projection.snapshot = None
            self.identity = None
            self.sidebar.navigation.reset()
            self.sidebar.projection.paint = None
            for group in self.sidebar.query(ChannelGroup):
                group._snapshot = None
            self.sidebar.projection.sync_spinner()

    async def session_updated(self, update: tuple[str, SessionDetails | None]) -> None:
        if not self.accepts_observation():
            return
        if self.sidebar.projection.has_snapshot():
            await self.sidebar.projection.publish(self.project(self.sidebar.projection.snapshot.wire))
        self.sidebar.navigation.mode_changed(self.sidebar.app.selected_mode)
        self.refresh()

    async def sync(self) -> None:
        """Reconcile tracked rows before a resumed screen accepts input."""
        async with self.lock:
            revision = self.service.views.revision()
            if self.sidebar.projection.has_snapshot() and self.read_identity(revision) == self.identity:
                await self.sidebar.projection.publish(self.project(self.sidebar.projection.snapshot.wire))
            else:
                await self.read(revision)

    async def actions_changed(self, _update: None) -> None:
        if not self.accepts_observation():
            self.identity = None
            return
        if self.sidebar.projection.has_snapshot() and self.sidebar.is_attached:
            await self.sidebar.projection.publish(self.sidebar.projection.snapshot)
        self.identity = None
        self.refresh()

    async def present_cached(self) -> None:
        """Paint the last observed projection; refresh disk state after activation."""
        if not self.accepts_observation():
            return
        state = self.sidebar.app._sidebar_snapshot
        if state is not None and (state.show_stopped, state.show_archived) == self.visible_filters:
            await self.sidebar.projection.publish(self.project(state))
        self.after_frame()

    @property
    def visible_filters(self) -> tuple[bool, bool]:
        settings = self.sidebar.app.settings
        return (settings.sidebar.show_stopped, settings.sidebar.show_archived)

    def settings_changed(self, update: PreferenceChange) -> None:
        if update.field in {SidebarSettings.show_stopped, SidebarSettings.show_archived}:
            self.identity = None
            self.refresh()

    def registry_names(self) -> list[str]:
        """Registered thread names on the wire (for view toggles)."""
        try:
            local_threads = self.sidebar.app.local_coordination_threads()
            return [name for name in wire(current_root()).registry.active_threads() if name not in local_threads]
        except Exception:
            return []

    def route_changed(self) -> bool:
        return self.sidebar.app.coordination_access.route_changed()

    async def coordination_updated(self, _event=None) -> None:
        service = self.sidebar.app.coordination_access.observed_service
        if service is not None:
            await self.bind(service)
        self.refresh()

    def accepts_observation(self) -> bool:
        from toad.widgets.side_bar import SideBar
        return self.enabled and self.sidebar.accepts_publication() and (not self.sidebar.query_ancestor(SideBar).collapsed)

    def refresh(self) -> None:
        if not self.accepts_observation():
            return
        if self.service is None:
            self.sidebar.display = False
            return
        self.after_frame()

    def start_read(self) -> None:
        if not self.accepts_observation():
            return
        try:
            if self.sidebar.screen is not self.sidebar.app.screen:
                return
            if self.route_changed():
                self.sidebar.display = False
            if self.pending:
                return
            revision = self.service.views.revision()
            if self.sidebar.display and self.read_identity(revision) == self.identity:
                return
            self.task = asyncio.create_task(self.refresh_checked(revision))
        except Exception:
            self.sidebar.display = False

    async def refresh_checked(self, revision: WireRevision) -> None:
        service = self.service
        try:
            from toad.comms_root import root_is_current
            if not await asyncio.to_thread(root_is_current, service.root):
                if self.service is service:
                    self.sidebar.display = False
                return
            if self.service is not service or not self.sidebar.accepts_publication():
                return
            await self.poll(revision)
            if self.service is service and self.identity == self.read_identity(revision):
                if not await asyncio.to_thread(root_is_current, service.root):
                    return
                if self.service is not service:
                    return
                self.sidebar.display = True
                if not self.sidebar.navigation.ready.is_set():
                    self.sidebar.call_after_refresh(self.sidebar.navigation.finish, self.sidebar.navigation.revision)
        except Exception:
            return

    async def poll(self, revision: WireRevision) -> None:
        service = self.service
        async with self.lock:
            if self.service is not service:
                return
            if self.sidebar.projection.has_snapshot() and self.read_identity(revision) == self.identity:
                await self.sidebar.app.mark_visible_thread_read()
                revision = service.views.revision()
                if self.service is not service:
                    return
                if self.identity == self.read_identity(revision):
                    self.identity = self.read_identity(revision)
                    await self.sidebar.projection.publish(self.project(self.sidebar.projection.snapshot.wire))
                    return
            await self.read(revision)

    async def read(self, revision: WireRevision) -> None:
        service = self.service
        try:
            actor = self.sidebar.session_thread
            filters = self.visible_filters
            await self.sidebar.app.mark_visible_thread_read()
            state = await asyncio.to_thread(service.views.viewer_snapshot, str(self.sidebar.app.project_dir), show_stopped=filters[0], show_archived=filters[1])
            if self.service is not service or not self.sidebar.accepts_publication():
                return
            if SidebarReadIdentity(revision, actor, filters) != self.read_identity(revision):
                return
            from toad.comms_root import root_is_current
            if not await asyncio.to_thread(root_is_current, service.root):
                if self.service is service:
                    self.sidebar.display = False
                return
            if self.service is not service:
                return
            snapshot = self.project(state)
            if state.read_marker_notice != self.read_marker_notice:
                self.read_marker_notice = state.read_marker_notice
                if state.read_marker_notice:
                    self.sidebar.notify(state.read_marker_notice, title='Read positions', severity='warning')
            app = self.sidebar.app
            previous_tabs = app.open_tabs
            app._sidebar_snapshot = state
            self.identity = SidebarReadIdentity(revision, actor, filters)
            await self.sidebar.projection.publish(snapshot)
            if app.open_tabs != previous_tabs:
                app.open_tabs_changed.publish(None)
        except (OSError, ValueError):
            return

@dataclass(frozen=True)
class PreparedThreadRow:
    source: ThreadRowPresentation
