@dataclass(frozen=True)
class ThreadRowsWork(SerializedWork[tuple[PreparedThreadRow, ...]], ContentAddressedWork[tuple[PreparedThreadRow, ...]], RendererWork[tuple[PreparedThreadRow, ...]]):
    rows: tuple[ThreadRowInput, ...]

    @property
    def inputs(self) -> tuple[ThreadRowPresentation, ...]:
